def _spec2(rid, exp, analytes, nvals, nsamples, nholes, fmt, missing, extra_remark="", npts_note=""):
    wl = {"ammonium": "640", "phosphate": "885", "sulfide": "670"}
    rec(rid,
        fmt=fmt,
        npts=f"{nvals} concentration results ({', '.join(analytes)}) for {nsamples} IW samples in {nholes} holes; calibration absorbance readings in supplementary files" + npts_note,
        missing=missing,
        prep="Yes (absorbance converted to concentration via standard curve)",
        prep_methods="1) IW subsample diluted and reacted with colour reagent (ammonium: phenol-hypochlorite indophenol blue; phosphate: ammonium molybdate / ascorbic acid molybdenum blue" + ("; sulfide: methylene blue" if "sulfide" in analytes else "") + "); 2) absorbance read at fixed wavelength; 3) linear calibration against standard series (e.g. 0-6000 uM NH4+); 4) dilution correction",
        target="Dissolved " + " and ".join(analytes) + " concentration in interstitial water vs depth",
        mode="Single-wavelength absorbance (double-beam UV-Vis, cuvette)",
        wl="; ".join(f"{a} {wl[a]}" for a in analytes),
        res="Spectral bandwidth 1.5 nm (Cary Advanced Reads report)",
        make="Agilent Cary 100 UV-Vis (README) - raw reports identify Cary 300, Advanced Reads 4.20",
        path="1 cm cuvette (standard; not stated in dataset)",
        ts="No (depth series)",
        chemo="No (univariate linear calibration)",
        refs=_IODP_REF[exp],
        remarks=f"Paper PDF is the {_IODP_PAPER[exp]}; data_by_hole tables give Analyte, Concentration (uM), Text ID, Test No., comments" + extra_remark,
        cond="Shipboard laboratory, room temperature colour development",
        absorb="Linear absorbance-concentration calibration slopes in workbooks (e.g. ~2165 uM per AU for NH4+ in U1512A)",
        refm="Gravimetric NH4Cl / KH2PO4 standard series and check standards (e.g. 1000 uM CHK)",
        gold=NA, peaks=NA,
        struct="Ammonium [NH4+]; phosphate [O-]P(=O)([O-])[O-]" + ("; sulfide [SH-]" if "sulfide" in analytes else "") + "; indophenol blue / molybdenum blue chromophores")


